function normalizeArabic(t) {
  if (t === null || t === undefined) return '';
  return String(t)
    .replace(/[\u0623\u0625\u0622]/g, '\u0627')
    .replace(/\u0629/g, '\u0647')
    .replace(/\u0649/g, '\u064a')
    .replace(/\u0640/g, '')
    .replace(/[\u064B-\u0652]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
// Builds the unified BARQLO Message Contract. The brain sees ONLY this contract,
// never the raw Telegram payload.
// Contract: tenant_id, channel, provider, channel_user_id, conversation_id,
// customer_id, message_id, timestamp, locale, payload.
// REJECTION RULE: channel missing/inactive OR tenant paused/cancelled => the
// contract status is 'rejected' and the Gate node below throws loudly AFTER the
// rejection is logged. No reply is sent for a rejected message, ever.
// ROLE (TBD-T1, do not guess): the new schema has NO tenant_members table, so a
// Telegram sender cannot yet be matched to an owner row. Draft default: EVERY
// sender is 'customer' for this tenant — including a person who is an owner
// elsewhere (role is per tenant, never global). Owner identification from a
// Telegram sender needs the TBD-T1 mapping decision before any owner command
// can be trusted from Telegram.
// IDENTITY (no linking here): the adapter does NOT create or link customers.
// It forwards channel_user_id only; the brain's Identify step resolves or
// provisionally creates the customer row and applies the evidence-only linking
// rules inside this tenant. Never link by name, photo, similarity, or across tenants.
const body = $('Telegram Trigger').first().json ?? {};
const msg = body.message ?? body;
const channel = $json ?? {};
const ok = Boolean(channel.tenant_id) && channel.active !== false && channel.tenant_status !== 'paused' && channel.tenant_status !== 'cancelled';
const contract = {
  tenant_id: channel.tenant_id ?? null,
  channel: 'telegram',
  provider: 'telegram',
  external_id: channel.external_id ?? null,
  channel_user_id: String(msg.from?.id ?? msg.chat?.id ?? ''),
  conversation_id: null, // resolved by the brain from conversations/messages; never invented here
  customer_id: null,     // resolved by the brain from customer_identities; never guessed here
  message_id: String(msg.message_id ?? ''),
  timestamp: msg.date ? new Date(msg.date * 1000).toISOString() : new Date().toISOString(),
  locale: 'ar-EG',
  payload: { text: msg.text ?? '', normalized_text: normalizeArabic(msg.text ?? ''), kind: msg.text ? 'text' : 'other' }
};
return [{ json: { contract, status: ok ? 'approved' : 'rejected', channel_id: channel.channel_id ?? null } }];

const c = $('Build Contract').first().json;
if (c.status === 'rejected') throw new Error('telegram_adapter_rejected: channel not registered, inactive, or tenant paused/cancelled — message was logged and never reached the brain');
return [{ json: c }];

const item = $input.first();
const data = item.json ?? {};
const failed = Boolean(item.error) || Boolean(data.error) || data.success === false || data.ok === false || data.status === 'error' || data.status === 'failed' || (typeof data.statusCode === 'number' && data.statusCode >= 400) || (typeof data.status === 'number' && data.status >= 400);
const raw = String(data.reply ?? data.reply_text ?? '').trim();
if (failed || raw.length <= 1800) return [{ json: { ...data, brain_status: failed ? 'failed' : 'ok' } }];
const max = 3500;
const target = Math.ceil(raw.length / Math.max(2, Math.ceil(raw.length / max)));
const parts = [];
let current = '';
function push() { if (current.trim()) parts.push(current.trim()); current = ''; }
for (const originalLine of raw.replace(/\r\n/g,'\n').split('\n')) {
  let line = originalLine;
  while (line.length > max) {
    let at = line.lastIndexOf(' ', max);
    if (at < Math.floor(max / 2)) at = max;
    const piece = line.slice(0, at).trim();
    if (current.trim()) push();
    if (piece) parts.push(piece);
    line = line.slice(at).trimStart();
  }
  const next = current ? current + '\n' + line : line;
  if (current.trim() && next.length > target) push();
  current = current ? current + '\n' + line : line;
}
push();
while (parts.length > 2 && parts[parts.length - 1].length < 600 && parts[parts.length - 2].length + parts[parts.length - 1].length + 1 <= max) {
  const tail = parts.pop();
  parts[parts.length - 1] += '\n' + tail;
}
return parts.map((part, index) => ({ json: { ...data, reply: (index + 1) + '/' + parts.length + '\n' + part, reply_text: (index + 1) + '/' + parts.length + '\n' + part, brain_status: 'ok', reply_part: index + 1, reply_parts: parts.length } }));
